// Example TEAMS for the Saved teams library. Each is a team definition (an org tree of agents
// with roles, models, caps, communication edges and rules plus a project profile), never a
// project: inserting one creates a new team and makes it active, without a goal, workspace,
// workflow or task. Projects are assigned to the team afterwards (src/projects.ts).
//
// - Plan → implement → review pipeline team: generated by src/pipeline.ts (worker caps, model
//   mappings and the Codex effort are configured at insert).
// - Wolfram-validated reasoning team: generated by src/samples.ts (one or two validators).
// - Product feature team: the bundled template assets/example-teams/product-feature-team.json.
//
// Model verification runs at insert (blocking unless `acceptUnverifiedModels` is explicit) and
// again for every project before it can resume.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { z } from "zod";
import { projectRoot } from "./config.ts";
import type { DetectedRuntime } from "./discovery.ts";
import { AppError, assert } from "./model.ts";
import {
  DEFAULT_CODEX_EFFORT,
  DEFAULT_MODELS,
  MAX_WORKERS,
  pipelineTeamTemplate,
} from "./pipeline.ts";
import {
  assessModels,
  wolframTeamTemplate,
  type ModelCheck,
} from "./samples.ts";
import type { TeamService } from "./service.ts";
import { PROJECT_TYPE_LABEL, type TeamProfile } from "./team-profiles.ts";
import {
  TeamTemplates,
  checkCompatibility,
  type TeamTemplate,
} from "./teams.ts";

export type ExampleField =
  | {
      key: string;
      label: string;
      kind: "count";
      min: number;
      max: number;
      default: number;
    }
  | { key: string; label: string; kind: "text"; default: string };

type Example = {
  id: string;
  /** One line: the team shape (lead + roles). */
  shape: string;
  fields: ExampleField[];
  build: (options: Record<string, unknown>) => TeamTemplate;
};

const text = (key: string, label: string, value: string): ExampleField => ({
  key,
  label,
  kind: "text",
  default: value,
});

let productCache: TeamTemplate | undefined;
/** The bundled product feature team (read once; validated like any imported template). */
export function productFeatureTemplate(): TeamTemplate {
  productCache ??= checkCompatibility(
    JSON.parse(
      readFileSync(
        join(
          projectRoot,
          "assets",
          "example-teams",
          "product-feature-team.json",
        ),
        "utf8",
      ),
    ),
  );
  return structuredClone(productCache);
}

const EXAMPLES: Example[] = [
  {
    id: "pipeline-review-team",
    shape:
      "Opus planner → Sonnet integrator (1-5 implementation + 1-5 fix workers), Fable adjudicator (4 Codex/Fable reviewers), Fable reporter",
    fields: [
      {
        key: "implementationWorkers",
        label: "Implementation workers",
        kind: "count",
        min: 1,
        max: MAX_WORKERS,
        default: 3,
      },
      {
        key: "fixWorkers",
        label: "Fix workers",
        kind: "count",
        min: 1,
        max: MAX_WORKERS,
        default: 3,
      },
      text("planner", "Planner model (Opus 5.5)", DEFAULT_MODELS.planner),
      text("worker", "Worker model (Sonnet 5.5)", DEFAULT_MODELS.worker),
      text(
        "codexReviewer",
        "Codex reviewer model",
        DEFAULT_MODELS.codexReviewer,
      ),
      text(
        "fableReviewer",
        "Fable reviewer model (Fable 5.1)",
        DEFAULT_MODELS.fableReviewer,
      ),
      text(
        "adjudicator",
        "Adjudicator model (Fable 5.1)",
        DEFAULT_MODELS.adjudicator,
      ),
      text("reporter", "Reporter model (Fable 5.1)", DEFAULT_MODELS.reporter),
      text("codexEffort", "Codex reviewer effort", DEFAULT_CODEX_EFFORT),
    ],
    build: (o) =>
      pipelineTeamTemplate({
        implementationWorkers: o.implementationWorkers,
        fixWorkers: o.fixWorkers,
        codexEffort: o.codexEffort,
        models: {
          planner: o.planner,
          worker: o.worker,
          codexReviewer: o.codexReviewer,
          fableReviewer: o.fableReviewer,
          adjudicator: o.adjudicator,
          reporter: o.reporter,
        },
      }),
  },
  {
    id: "wolfram-validated-team",
    shape: "Opus 5.5 lead → 1-2 Wolfram validators (kernel-validated steps)",
    fields: [
      {
        key: "wolframAgents",
        label: "Wolfram validators",
        kind: "count",
        min: 1,
        max: 2,
        default: 2,
      },
      text("leadModel", "Lead model (Opus 5.5)", "claude-opus-5-5"),
      text("wolframModel", "Wolfram model", "default"),
    ],
    build: (o) =>
      wolframTeamTemplate({
        wolframAgents: o.wolframAgents,
        leadModel: o.leadModel,
        wolframModel: o.wolframModel,
      }),
  },
  {
    id: "product-feature-team",
    shape:
      "Engineering Manager → frontend, backend, QA, technical writer; mandatory code reviewer; advisory security reviewer",
    fields: [
      text("claudeModel", "Claude agents' model", "default"),
      text("codexModel", "Codex agents' model", "default"),
    ],
    build: (o) => {
      const t = productFeatureTemplate();
      for (const a of t.agents) {
        const m = a.environment === "claude" ? o.claudeModel : o.codexModel;
        if (typeof m === "string" && m.trim()) a.model = m.trim();
      }
      return t;
    },
  },
];

const optionsSchema = z
  .record(z.string().max(40), z.union([z.string().max(200), z.number()]))
  .default({});

function find(id: string) {
  const e = EXAMPLES.find((x) => x.id === id);
  if (!e) throw new AppError(404, "not_found", `No example team ${id}`);
  return e;
}
/** Defaults filled in, counts as integers inside their bounds, text trimmed (empty = default). */
function options(e: Example, input: unknown) {
  const raw = optionsSchema.parse(input);
  for (const k of Object.keys(raw))
    assert(
      e.fields.some((f) => f.key === k),
      "unknown_option",
      `Unknown option ${k} for this example team`,
      400,
    );
  return Object.fromEntries(
    e.fields.map((f) => {
      const v = raw[f.key];
      if (f.kind === "count") {
        const n = v === undefined ? f.default : Number(v);
        assert(
          Number.isInteger(n) && n >= f.min && n <= f.max,
          "invalid_option",
          `${f.label} must be a whole number from ${f.min} to ${f.max}`,
          400,
        );
        return [f.key, n];
      }
      const s = v === undefined ? "" : String(v).trim();
      return [f.key, s || f.default];
    }),
  );
}

/** Insert-time model check of a template (keys stand in for agent ids). */
export function checkTemplateModels(
  t: TeamTemplate,
  runtimes: DetectedRuntime[] | undefined,
): ModelCheck {
  const r = assessModels(
    t.agents.map((a) => ({
      id: a.key,
      name: a.name,
      environment: a.environment,
      model: a.model,
      effort: a.effort,
    })),
    runtimes,
    {
      ...(t.project?.intendedLead
        ? { leadId: t.project.lead, intendedLead: t.project.intendedLead }
        : {}),
      expectations: t.project?.expectations ?? {},
    },
  );
  return {
    verified: !r.issues.length,
    checkedAt: new Date().toISOString(),
    ...r,
  };
}

const insertSchema = z
  .object({
    options: optionsSchema,
    teamName: z.string().trim().min(1).max(80).optional(),
    /** Insert although the model check did not pass; projects still verify before resuming. */
    acceptUnverifiedModels: z.boolean().default(false),
  })
  .strict();

export class ExampleTeams {
  service: TeamService;
  teams: TeamTemplates;
  runtimes: () => DetectedRuntime[] | undefined;
  constructor(
    service: TeamService,
    teams: TeamTemplates,
    runtimes: () => DetectedRuntime[] | undefined,
  ) {
    this.service = service;
    this.teams = teams;
    this.runtimes = runtimes;
  }
  list() {
    return EXAMPLES.map((e) => {
      const template = e.build(options(e, {}));
      const type = template.project?.type ?? "free-form";
      return {
        id: e.id,
        name: template.name,
        shape: e.shape,
        description: template.description,
        projectType: type,
        projectLabel: PROJECT_TYPE_LABEL[type],
        fields: e.fields,
        template,
      };
    });
  }
  /** The configured template, its model check and the structural insert preview; no writes. */
  async preview(id: string, input: unknown) {
    const e = find(id);
    const body = z
      .object({ options: optionsSchema })
      .strict()
      .parse(input ?? {});
    const template = e.build(options(e, body.options));
    const modelCheck = checkTemplateModels(template, this.runtimes());
    // Environment/model availability is reported by the model check above.
    const preview = await this.teams.preview({
      envelope: {
        format: "agentteam.team-template",
        schemaVersion: 3,
        template,
      },
      allowUnknownModels: true,
      allowUninstalledEnvironments: true,
    });
    return { template, modelCheck, preview };
  }
  /** Insert the example as a new, active team with its project profile; creates no project. */
  insert(id: string, input: unknown) {
    const e = find(id);
    const body = insertSchema.parse(input ?? {});
    const template = e.build(options(e, body.options));
    const modelCheck = checkTemplateModels(template, this.runtimes());
    if (!modelCheck.verified && !body.acceptUnverifiedModels)
      throw new AppError(
        409,
        "models_unverified",
        `Model verification did not pass: ${modelCheck.issues.join("; ")}. Fix the model mapping or insert explicitly unverified (projects stay blocked until their models verify).`,
      );
    const result = this.teams.insertTemplate(
      template,
      {
        ...(body.teamName ? { teamName: body.teamName } : {}),
        allowUnknownModels: true,
        allowUninstalledEnvironments: true,
      },
      (r) => {
        if (!r.profile) return;
        const profile: TeamProfile = {
          ...r.profile,
          source: { template: template.name, example: e.id },
          modelCheck: {
            ...modelCheck,
            // Keys -> the inserted agents' ids.
            resolved: modelCheck.resolved.map((x) => ({
              ...x,
              agentId: r.idMap[x.agentId] ?? x.agentId,
            })),
          },
        };
        this.service.store.put("team-profile", profile);
        r.profile = profile;
      },
    );
    return { ...result, modelCheck, example: e.id };
  }
}
